contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Call sequence: non-owner attempts to trigger a withdrawal/send; on P this must not reduce c balance,
    // but on M (where onlyOwner always passes) it can.
    function run(address payable target, uint256 sendAmt) public payable {
        // ensure this test contract has enough balance to use with c.sendMoney if needed
        require(address(this).balance >= msg.value);

        // Precondition: target is some address; we won't trust target to be owner.
        // Record contract balance before the operation
        uint256 before = address(c).balance;

        // Attempt to call functions guarded by onlyOwner from a non-owner caller (this contract).
        // We choose sendMoney because it can move arbitrary Ether out of c when onlyOwner is lax.
        // We call it with a value parameter; it does not itself send ETH from msg.sender, but instructs c to call _target with value.
        // On original P this call should revert (require in modifier), or at least not change c's balance; on M it will execute and may decrease c balance.
        // We make the call as a plain external call so revert behavior is captured by solidity: it will revert the whole run if underlying reverts.
        // To observe non-revert but unauthorized acceptance, we allow both possibilities by using try/catch on low-level call to c.sendMoney.

        // Perform the state-changing external call
        // Note: per the rules, state-changing calls must be top-level statements.
        c.sendMoney(target, sendAmt);

        // Observe balance after the attempted operation
        uint256 after = address(c).balance;

        // GENERAL ASSERTION: if caller is not the owner then c's balance must not decrease due to our call — i.e., after >= before.
        // We can't read owner directly from invisibly, but in P onlyOwner will prevent non-owner changes; in M it allows them.
        assert(after >= before);
    }

    // Allow this test contract to receive ETH for preparing balances
    receive() external payable {}
}

