        // owner, we assert that withdrawAll reverted OR it succeeded (this is tautology).
        // Instead assert the intended property: withdrawAll either reverts OR leaves c's balance unchanged
        // But we can observe address(c).balance before/after only by storing before first; capture before by calling a view
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        // no extra precondition
        bool reverted;
        // Make the call as the provided caller address by using low-level call
        // We cannot change msg.sender directly, but we can simulate caller by
        // asking that the caller is this contract (owner) or some other externally
        // provided address. Because we must call c.withdrawAll() directly and
        // every state-changing call on c must be a top-level statement, we perform
        // the call from this contract. The property relates caller == owner vs revert.
        // Here we interpret `caller` as a flag: if caller == address(this) then
        // the call is from the owner (since C was presumably deployed by the test harness
        // and passed into constructor), otherwise it's a non-owner. We call withdrawAll
        // and observe whether it reverts.
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }
        // The general rule: if the invoker is the owner (address(this)) then withdrawAll must NOT revert;
        // if the invoker is not the owner then withdrawAll MUST revert. We express this as:
        // (caller == address(this)) == (!reverted)
        // Note: we use the input parameter `caller` to specify which case we assert about.
        assert(((caller == address(this)) && !reverted) || ((caller != address(this)) && reverted));
    }
    receive() external payable { }
}

