pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker payableTarget;

    function setUp() public { c = new C(); payableTarget = new Attacker(); }

    // fuzz parameters: amount to send and caller address (actor)
    function testFuzz_property(uint256 amt, address actor) public {
        // keep amount in reasonable bounds and actor not zero
        vm.assume(actor != address(0));
        amt = bound(amt, 0, 1 ether);

        // fund the contract with some ether to be sent
        vm.deal(address(this), 2 ether);
        // deposit into c by sending ETH to fallback (increments depositsCount but also funds contract)
        c.sendMoney{value: 0}(address(this), 0); // harmless call to ensure c exists; not necessary but fine
        // directly fund C by sending ETH to it
        (bool s,) = address(c).call{value: 1 ether}("");
        require(s);

        // ensure the target can accept ETH (Attacker has payable fallback)
        // actor will attempt to call sendMoney to direct funds to payableTarget
        vm.deal(actor, 1 ether);
        vm.prank(actor);

        bool ok;
        try c.sendMoney(address(payableTarget), amt) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule (single assertion): In the correct contract, a non-owner caller cannot decrease contract balance via sendMoney.
        // We assert that either the call reverted (ok==false) or the contract balance remains at least what it was before the call minus zero (i.e., didn't drop below original - but since we can't read previous local here, we rely on specific property):
        // The reference ensures that if caller is not owner, sendMoney cannot transfer funds away, so after call address(c).balance == 1 ether.
        // This assertion is satisfied by the reference for all inputs; the mutant (which allows anyone) will for some inputs make address(c).balance < 1 ether and cause this assertion to fail.
        assertTrue(address(c).balance == 1 ether);
    }
}

