pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: an address that will act as the caller (not the owner) and an amount to attempt to withdraw
    function testFuzz_property(address caller, uint256 amount) public {
        // keep domain wide but sensible
        vm.assume(caller != address(0));
        // ensure caller is not the owner (owner set in setUp to address(this))
        vm.assume(caller != address(this));

        // fund the contract with some ETH so there's a balance to try to withdraw
        uint256 seedBalance = 1 ether;
        vm.deal(address(this), seedBalance);
        // send some ETH into c from the test contract (owner)
        c.sendMoney{value: 0}(address(this), 0); // harmless; not required but keeps shape
        (bool okFund, ) = address(c).call{value: seedBalance}("\x00");
        require(okFund, "funding failed");

        // bound amount to a reasonable range: allow 0..seedBalance*2 so fuzz can try >balance too
        uint256 v = bound(amount, 0, seedBalance * 2);

        // The adversarial counterpart here is a normal payable receiver that accepts ETH.
        // Deploy a simple receiver that just accepts funds so a sendMoney to it will succeed.
        Receiver r = new Receiver();

        // ensure the caller has enough ETH to attempt the call (prank sender)
        vm.deal(caller, v);

        // Non-owner attempts to instruct c to send v to the receiver r
        vm.prank(caller);
        bool ok;
        try c.sendMoney(address(r), v) {
            ok = true;
        } catch {
            ok = false;
        }

        // ASSERTION: For the correct contract, when a non-owner (caller) invokes sendMoney, the contract balance must NOT decrease.
        // We read address(c).balance as the observable. This must hold for ALL inputs (caller != owner).
        // The mutant that removes the ownership check will allow the non-owner to withdraw funds for some inputs (v>0), breaking this.
        assertTrue(address(c).balance == seedBalance, "contract balance changed from owner-only invariant");
    }
}

