pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 amt) public {
        // keep amt in a reasonable range
        amt = bound(amt, 0, 1 ether);
        // make sure caller is not the owner (owner is address(this) that deployed C in setUp)
        vm.assume(caller != address(this));

        // fund the contract with some balance to attempt a send
        vm.deal(address(c), 1 ether);

        // deploy a reverter callee: it will revert on receive, so a successful low-level call from C would return false
        Reverter rev = new Reverter();

        // Have the fuzzed caller attempt to invoke sendMoney to the reverter with amt value
        vm.deal(caller, amt);
        vm.prank(caller);
        bool ok;
        // call sendMoney; capture whether it succeeded (did not revert)
        try c.sendMoney(address(rev), amt) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule (one assertion): For the correct contract, non-owner callers cannot invoke sendMoney, so contract balance remains unchanged => any observed success (ok==true) must be false.
        // We assert the contract reports no successful send for non-owner caller (reference satisfies this for all inputs; mutant that relaxes onlyOwner will allow some caller/amt to make ok==true)
        assertTrue(!ok);
    }
}

// Adversarial counterpart: reverting callee to distinguish behavior when C actually attempts to call out
contract Reverter {
    fallback() external payable {
        revert("nope");
    }
    receive() external payable {
        revert("nope");
    }
}

