contract Derived is C {
    // override withdraw to perform a no-op so that if withdrawAll calls withdraw(address(this).balance) it will call this override and not actually transfer funds
    function withdraw(uint _value) public override onlyOwner {
        // do nothing (simulate overridden behavior)
    }
}

contract RevertingRecipient {
    bool public shouldRevert;
    constructor(bool _r) payable { shouldRevert = _r; }
    receive() external payable {
        if (shouldRevert) revert("no receive");
    }
}

