pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz: amount is the ether deposited into C; ownerIsReverter selects whether owner is a rejecting contract
    function testFuzz_property(uint256 amount, bool ownerIsReverter) public {
        // keep amount in a reasonable range so vm.deal works and to avoid overflow in test harness
        amount = bound(amount, 0, 1 ether);

        // Deploy adversarial or benign owner contract according to the fuzzed flag
        address ownerAddr;
        if (ownerIsReverter) {
            Reverter r = new Reverter();
            ownerAddr = address(r);
        } else {
            GoodReceiver g = new GoodReceiver();
            ownerAddr = address(g);
        }

        // fund the owner (so transfers to it could succeed if they are allowed)
        vm.deal(ownerAddr, 1 ether);

        // Make sure C has some balance to withdraw
        if (amount > 0) {
            vm.deal(address(this), amount);
            // send to c from this contract
            (bool s,) = address(c).call{value: amount}("");
            require(s);
        }

        // Confirm precondition: contract balance equals the amount
        // Now impersonate the owner on c: set msg.sender to ownerAddr when calling withdrawAll
        vm.prank(ownerAddr);

        // Call withdrawAll and capture whether it succeeded (some mutants may revert)
        bool ok;
        try c.withdrawAll{gas: gasleft()}() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property for the reference: after withdrawAll returns (or would have), the contract balance is zero.
        // For the reference contract this holds for all inputs; the mutant that uses direct transfer to msg.sender
        // can revert when owner is a rejecting contract, leaving the contract balance non-zero (or causing revert).
        assertTrue(address(c).balance == 0);
    }
}

