            ok = false;
        }

        // General rule to assert: after calling withdraw(amount) as owner-from-helper, either the withdraw call succeeded
        // and contract balance decreased by amount, or it reverted and contract balance remains unchanged. For the reference
        // implementation using transfer, a revert will occur when the recipient (helper) fails to accept ETH; thus when the
        // external recipient path aborts, the call must revert rather than silently succeed leaving contract balance unchanged.
