        // reverted (ok == false), contract balance is unchanged. This property holds for the reference but the mutant that
        // ignores success of call can return ok==true while balance remains unchanged, violating the property.

        if (ok) {
            // withdrew: balance reduced
            assertTrue(address(c).balance == (1 ether - amount));
        } else {
            // reverted: balance unchanged
            assertTrue(address(c).balance == 1 ether);
        }
    }
}

// Helper that will call c.withdraw as its own msg.sender and forward any received ETH to a target
contract CallerHelper {
    C immutable c;
    address forwardTarget;

    constructor(C _c) {
        c = _c;
    }

    function setForwardTarget(address _t) external {
        forwardTarget = _t;
    }

    // Called to invoke withdraw on C as this contract
    function callWithdraw(uint256 amount) external {
        c.withdraw(amount);
    }

    // Receive will forward to target; forwarding to Reverter will cause revert
    receive() external payable {
        if (forwardTarget != address(0)) {
            (bool s, ) = forwardTarget.call{value: msg.value}("");
            require(s);
        }
    }
}

// Adversarial reverter: always reverts on receive/fallback
contract Reverter {
    receive() external payable {
        revert("revert on receive");
    }
